const alert = $input.first().json.body || $input.first().json;
const riskScore = alert.risk_score || 0;
const severity = alert.severity || 'medium';
const category = alert.category || 'system';

let blockedUntil = new Date();
let jailType = 'none'; // Usaremos esto para el log

// Lógica unificada con el cálculo de riesgo
if (riskScore >= 80 || severity === 'critical') {
  blockedUntil.setDate(blockedUntil.getDate() + 30);
  jailType = 'critical'; 
} else if (riskScore >= 60 || severity === 'high') {
  blockedUntil.setHours(blockedUntil.getHours() + 24);
  jailType = 'high'; // <--- Ahora irá a la nueva cárcel HIGH
} else if (riskScore >= 40 || severity === 'medium') {
  blockedUntil.setTime(blockedUntil.getTime() + 30 * 60 * 1000); // 30 min en ms
  jailType = 'medium';
} else {
  return [{ json: { ...alert, block_decision: 'no_block', reason: 'Umbral no alcanzado' } }];
}

alert.blocked_until = blockedUntil.toISOString();
alert.block_decision = 'block';
alert.block_timestamp = new Date().toISOString();
alert.jail_type = jailType; // ESTO ES CLAVE PARA EL LOG
alert.firewall_action = 'block';
alert.reason = 'Intrusión perimetral confirmada: ' + alert.rule_name;

return [{ json: alert }];

// Forzamos a n8n a leer del nodo original de decisión
const result = $('¿Bloquear?').item.json;

const isBlocked = result.block_decision === 'block';

const report = {
  type: 'ip_block_event',
  timestamp: new Date().toISOString(),
  action: 'ip_blocking',
  status: isBlocked ? 'blocked' : 'not_blocked',
  severity: result.severity,        
  category: result.rule_name,

  // 🛠️ ALIAS PARA EL DASHBOARD: Mapeamos los campos exactos que pide el gráfico roto
  ip_address: result.source_ip, 
  is_active: isBlocked, // Mandamos true si fue bloqueado, false si no

  details: {
    ip: result.source_ip,
    threat_score: result.risk_score,
    reason: result.reason || 'Alerta crítica detectada', 
    blocked_until: result.blocked_until,
    firewall_executed: true          
  },
  workflow: 'auto_blocking_v1'
};

console.log('Reporte con campos de compatibilidad:', JSON.stringify(report, null, 2));

return [{ json: report }];
